typedef struct disclosure disclosure_t;             /* behaviour: owns the state */
struct disclosure { int expanded; void (*paint)(void *ud, int expanded); void *ud; };

void disclosure_toggle(disclosure_t *d) {           /* one owner, one transition */
    d->expanded = !d->expanded;
    d->paint(d->ud, d->expanded);                   /* markup half: consumer's callback */
}
/* the consumer supplies the markup and registers it once:
   disclosure_t d = {0, draw_button, &canvas};  disclosure_toggle(&d); */
